import os, xml.etree.ElementTree as ET, dateutil.parser
OUTDIR = '/tmp/scout_feeds'
for name in os.listdir(OUTDIR):
    if not name.endswith('.xml'): continue
    path = os.path.join(OUTDIR, name)
    try:
        root = ET.parse(path).getroot()
        items = root.findall('.//item')
        print(name, 'items count:', len(items))
        if items:
            pub = items[0].find('pubDate')
            if pub is not None:
                print('  first item pubDate:', pub.text)
                try:
                    parsed = dateutil.parser.parse(pub.text)
                    print('  parsed:', parsed)
                except Exception as e:
                    print('  parse error:', e)
    except Exception as e:
        print('Error reading', name, ':', e)
